pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Fund the contract so it has Ether to send
        vm.deal(address(c), 100 ether);
    }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Keep amount within contract's balance to avoid revert due to insufficient funds
        vm.assume(amount <= 100 ether);
        // Record balance before
        uint256 contractBalanceBefore = address(c).balance;
        // Owner calls sendTo
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        // Balance after
        uint256 contractBalanceAfter = address(c).balance;
        // The contract's balance must decrease by exactly the sent amount
        assertTrue(contractBalanceAfter == contractBalanceBefore - amount);
    }
}

